import{advanceRotors}from'./animation.js?v=balance-8';
import{EXTRA_SPECS,createExtraAircraft}from'./fleet.js?v=balance-8';
import{VoxelPart}from'./voxels.js?v=balance-8';
const B=globalThis.BABYLON;
export const SPECS={prop:{name:'Kestrel ST–6',description:'High-lift wings. Rugged gear.<br>Built for the places beyond the runway.',mass:1250,area:18,cl0:.2,cla:4.8,clmax:1.5,cd:.034,k:.055,thrust:5100,power:440000,stall:27,cruise:73,gearHeight:1.73,roll:1.05,pitch:.48,yaw:.33,span:13.4},jet:{name:'Peregrine X–2',description:'Swept wings. Twin afterburners.<br>Precision, speed, and a little excess.',mass:3500,area:22,cl0:.1,cla:4.3,clmax:1.3,cd:.024,k:.073,thrust:30000,power:0,stall:52,cruise:215,gearHeight:1.9,roll:1.85,pitch:.62,yaw:.38,span:11.2},...EXTRA_SPECS};
export const AIRCRAFT_TYPES=['prop','swift','jet','ufo'];
export const AIRCRAFT_TAGS={prop:'AGILE · FUEL EFFICIENT',swift:'TWIN TURBOPROPS · MIDRANGE',jet:'HIGH SPEED · AFTERBURNERS',ufo:'GRAVITIC LIFT · ION DRIVE'};
export function createAircraft(scene,type){if(EXTRA_SPECS[type])return createExtraAircraft(scene,type);const jet=type==='jet',root=new B.TransformNode('aircraft '+type,scene);root.rotationQuaternion=B.Quaternion.Identity();const parts=[],surfaces={ailerons:[],flaps:[],elevators:[],rudders:[],gear:[],wheels:[],props:[]};
 const part=(name,size=.075,origin=[0,0,0],parent=root)=>{const p=new VoxelPart(name,scene,parent,size*.8,origin);parts.push(p);return p;};
 const hull=part('fuselage monocoque');
 if(!jet){hull.volume([-.91,.91,-4.6,1.05,-4.8,3.5],(x,y,z)=>{if(y<-.7)return null;const t=(z+4.8)/8.3;let w=z<-1.1?.19+(z+4.8)*.15:z>2?.72-(z-2)*.16:.76;let cy=z<-1.1?-.14:0;let hh=z<-1.1?.25+(z+4.8)*.08:.68;const r=(x/w)**2+((y-cy)/hh)**2;if(r>1)return null;if(z>-.8&&z<1.5&&y>.08&&Math.abs(x)<w-.12)return null;return y<-.23?'dark':Math.abs(y+.08)<.12?'orange':z<-2.8?'orange':'ivory';});}
 else{hull.volume([-1.08,1.08,-.76,.87,-5.2,6.2],(x,y,z)=>{const w=z>2.2?Math.max(.08,1.02*(6.3-z)/4.1):z<-2?.82+(z+2)*.15:1.02;const hh=z>2.2?.68*Math.sqrt(Math.max(.03,(6.4-z)/4.2)):.65;const r=(x/w)**2+(y/hh)**2;return r<1?(y<-.24?'dark':z>5?'black':Math.abs(x)>.81?'orange':'jet'):null;});}
 hull.build();
 // Cockpit interior, translucent-looking stepped glazing, individual frame bars.
 const cockpit=part('cockpit glass and framing',.055);const cz=jet?1.6:.55,cw=jet?.69:.71;
 cockpit.volume([-cw,cw,.35,jet?1.65:1.65,cz-1.05,cz+1.07],(x,y,z)=>{const tt=(z-cz)/1.16,hh=jet?1.08*Math.sqrt(Math.max(0,1-tt*tt)):.87;const rr=(x/cw)**2+((y-.55)/hh)**2;if(y<.56||rr>1||rr<.78)return null;const frame=Math.abs(z-cz)<.04||Math.abs(z-cz-.65)<.04||Math.abs(x)<.04||y<.65;return frame?'dark':y>1.14?'glassLight':'glass';}).build();
 const interior=part('seats instrument panel and controls',.055);for(const x of jet?[0]:[-.34,.34]){interior.box(x,.12,cz-.32,.43,.12,.55,'black').box(x,.43,cz-.6,.43,.65,.12,'orange').box(x,.7,cz-.6,.23,.22,.14,'black').rod([x,.05,cz],[x,.5,cz+.1],.045,'metal');}interior.box(0,.48,cz+.72,jet?1:1.3,.28,.13,'dark');for(let x=-.4;x<=.4;x+=.16)interior.box(x,.52,cz+.63,.1,.08,.025,'green');interior.build();
 const panel=part('panel seams door handles rivets and vents',.045);for(const s of[-1,1]){for(let z=-2.7;z<2;z+=.38){panel.box(s*(jet?.93:.74),-.1,z,.035,.065,.06,'metal');}if(!jet){panel.box(s*.78,.1,.06,.035,.88,.045,'dark').box(s*.79,.1,-.52,.035,.075,.2,'metal');for(let i=0;i<7;i++)panel.box(s*.63,.25,2.1+i*.13,.045,.18,.05,'black');}else{for(let i=0;i<8;i++)panel.box(s*.78,.57,-.9-i*.12,.28,.025,.055,'black');}}panel.build();
 for(const side of[-1,1]){
  const wing=part((side<0?'port':'starboard')+' wing structure',.075);
  if(!jet)wing.volume([side<0?-6.7:.72,side<0?-.72:6.7,.79,1.2,-.22,1.83],(x,y,z)=>{const ax=Math.abs(x),lead=1.82-(Math.max(0,ax-5.3))*.28,hh=.115*Math.sin(Math.PI*Math.max(0,Math.min(1,(z+.25)/(lead+.25))));if(Math.abs(y-(1.03+ax*.013))>hh)return null;return ax>6.05?'orange':Math.abs(z-1.47)<.12?'cream':Math.abs(x%1.02)<.036?'cream':'ivory';});
  else wing.volume([side<0?-5.6:.7,side<0?-.7:5.6,-.26,.12,-3.45,2],(x,y,z)=>{const ax=Math.abs(x),lead=2-ax*.57,trail=-1.85-ax*.22;if(z>lead||z<trail||Math.abs(y+.02-ax*.02)>.09)return null;return ax>5.06?'orange':z>lead-.22?'dark':Math.abs(x%1.1)<.04?'metal':'jet';});wing.build();
  const az=jet?-2.54:-.2,ay=jet?.02:1.08,ax=side*(jet?4.2:4.55);
  const aileron=part((side<0?'port':'starboard')+' aileron',.06,[ax,ay,az]);aileron.box(0,0,-.25,jet?2.25:3.5,.12,.47,jet?'orange':'ivory').box(side*(jet?.85:1.3),0,-.25,.34,.13,.48,'orange').build();surfaces.ailerons.push({node:aileron.node,side});
  const flap=part((side<0?'port':'starboard')+' slotted flap',.06,[side*2,jet?-.03:1.06,jet?-2.02:-.21]);flap.box(0,0,-.24,jet?1.75:1.8,.13,.48,jet?'jet':'ivory').box(0,-.055,-.12,1.7,.05,.06,'metal').build();surfaces.flaps.push(flap.node);
  const hinge=part('surface hinges',.045);for(const x of jet?[side*3.4,side*4.8]:[side*3.2,side*4.5,side*6])hinge.box(x,ay-.08,az,.1,.1,.16,'metal');hinge.build();
  if(!jet){const strut=part('wing lift struts',.055);strut.rod([side*.68,-.45,-.6],[side*3.85,.98,.84],.065,'metal').rod([side*.69,-.4,-.6],[side*3.85,.98,-.03],.06,'ivory').rod([side*2,.12,.03],[side*2,1.02,.5],.04,'dark').build();}
  const tail=part('horizontal stabilizer',.06);const ty=jet?.49:.4,tz=jet?-4.05:-3.85;tail.volume([side<0?(jet?-2.9:-2.35):.14,side<0?-.14:jet?2.9:2.35,ty-.075,ty+.075,tz-.5,tz+.9],(x,y,z)=>{const lead=tz+.9-Math.abs(x)*(jet?.35:.13);return z<lead?Math.abs(x)>(jet?2.4:1.9)?'orange':jet?'jet':'ivory':null;}).build();
  const elev=part('elevator',.055,[side*(jet?1.48:1.23),ty,tz-.51]);elev.box(0,0,-.2,jet?2.55:2.1,.11,.38,jet?'jet':'ivory').box(side*(jet?1.04:.84),0,-.2,.32,.115,.38,'orange').build();surfaces.elevators.push(elev.node);
  const nav=part('navigation light',.04);nav.box(side*(jet?5.57:6.72),jet?.07:1.15,jet?-1.8:.75,.12,.12,.2,side<0?'red':'green').build();
 }
 for(const x of jet?[-1.14,1.14]:[0]){const fin=part('vertical stabilizer',.065,[x,jet?.25:.1,jet?-4.1:-3.95]);fin.volume([-.08,.08,0,jet?2.35:2.6,-.1,1.8],(xx,y,z)=>{const lead=1.8-y*.47;return z<lead?(y>1.95?'orange':z<.15?'dark':jet?'jet':'ivory'):null;}).build();if(jet)fin.node.rotation.z=x<0?.18:-.18;
 const rudder=part('rudder',.055,[0,.25,-.12],fin.node);rudder.box(0,.8,-.21,.12,1.72,.4,'orange').build();surfaces.rudders.push(rudder.node);}
 const antenna=part('antennas pitot tubes aerials',.035);antenna.rod([0,jet?.75:1.12,-1.6],[0,jet?1.55:1.8,-1.82],.038,'dark').rod([-3,jet?-.04:.99,1.3],[-3,jet?-.04:.99,2.1],.032,'metal');antenna.build();
 for(const [i,pos]of(jet?[[0,-.55,3.3],[-1.35,-.6,-.75],[1.35,-.6,-.75]]:[[0,-.45,2.15],[-1.4,-.45,-.72],[1.4,-.45,-.72]]).entries()){
 const g=part('landing gear '+i,.045,pos);g.rod([0,0,0],[0,-.78,0],.074,'metal').rod([.12,-.05,-.25],[0,-.68,0],.045,'dark').box(0,-.24,0,.19,.27,.18,'ivory').box(0,-.61,0,.12,.31,.11,'lightMetal');if(i)g.rod([0,0,0],[-Math.sign(pos[0])*.45,.1,.28],.06,'metal');g.build();surfaces.gear.push({node:g.node,index:i});
 const wheel=part('wheel tire hub brake rotor '+i,.04,[0,-.85,0],g.node);wheel.volume([-.18,.18,-.32,.32,-.32,.32],(x,y,z)=>{const r=Math.hypot(y,z);if(r>.32)return null;if(r<.14)return Math.abs(x)>.12?'metal':'dark';if(r>.28&&Math.floor(Math.atan2(y,z)*16)%2===0)return'black';return'rubber';}).build();surfaces.wheels.push(wheel.node);
 const hub=part('wheel axle '+i,.035,[0,-.85,0],g.node);hub.box(0,0,0,.45,.07,.07,'metal').build();}
 if(!jet){const cowling=part('turboprop cowling and intake',.055);cowling.volume([-.63,.63,-.62,.62,2.85,3.8],(x,y,z)=>{const r=Math.hypot(x,y),rad=.57-(z-2.85)*.08;return r<rad?(z>3.55?'dark':Math.abs(y)<.1?'orange':'ivory'):null;}).box(0,-.43,3.44,.53,.18,.08,'black').build();
 const prop=part('propeller hub and spinner',.045,[0,0,3.88]);prop.volume([-.24,.24,-.24,.24,-.12,.39],(x,y,z)=>Math.hypot(x,y)<.24*(.47-z)/.6?'orange':null).build();surfaces.props.push(prop.node);
 for(let i=0;i<4;i++){const blade=part('carbon propeller blade '+i,.035,[0,0,0],prop.node);blade.volume([-.14,.14,.19,1.42,-.08,.08],(x,y,z)=>{const w=y>1.2?.09:.14;return Math.abs(x-(y-.6)*.055)<w?y>1.2?'yellow':'black':null;}).build();blade.node.rotation.z=i*Math.PI/2;blade.node.rotation.y=.15;}
 for(const s of[-1,1]){const exhaust=part('turbine exhaust pipe',.04);exhaust.rod([s*.48,-.32,2.9],[s*.72,-.4,2.62],.12,'metal').box(s*.75,-.42,2.55,.2,.19,.06,'black').build();}}
 else{for(const s of[-1,1]){const engine=part('jet intake compressor nacelle nozzle',.065);engine.volume([s*1.23-.66,s*1.23+.66,-.83,.58,-5.3,1.45],(x,y,z)=>{const r=Math.hypot(x-s*1.23,y+.15),rad=z>1?.54:z<-4.5?.47:.62;if(r>rad)return null;if((z>1.16||z<-4.91)&&r<rad-.12)return null;return z>1.12?'metal':z<-4.75?'dark':Math.abs(z+4.45)<.12?'metal':Math.abs(x-s*1.23)>.55?'cream':'jet';}).build();
 const turbine=part('compressor blades',.045,[s*1.23,-.15,1.15]);for(let i=0;i<10;i++){const a=i*Math.PI/5;turbine.rod([Math.cos(a)*.11,Math.sin(a)*.11,0],[Math.cos(a+.3)*.4,Math.sin(a+.3)*.4,0],.055,'dark');}turbine.build();
 const nozzle=part('afterburner ring',.045,[s*1.23,-.15,-5.24]);nozzle.volume([-.4,.4,-.4,.4,-.06,.06],(x,y,z)=>{const r=Math.hypot(x,y);return r<.4&&r>.29?'orange':r<.15?'dark':null;}).build();}}
 const service=part('inspection plates fasteners hinges and intake rims',.04);for(const side of[-1,1]){const x=side*(jet?1.02:.79);for(let z=-1.8;z<1.5;z+=.65){service.box(x,.15,z,.035,.22,.32,'cream');for(const d of[-.11,.11])service.box(x+side*.02,.15+d,z,.04,.035,.035,'metal');}for(let z=jet?-4.8:2.6;z<(jet?-4.15:3.45);z+=.11)service.box(side*(jet?1.7:.59),-.05,z,.04,.08,.045,'metal');}service.build();
 return{root,parts,surfaces,type,spec:SPECS[type],voxelCount:parts.reduce((n,p)=>n+p.count,0),partCount:parts.length,dispose(){root.dispose(false,false);}};
}
export function animateAircraft(plane,dt,state){const s=plane.surfaces,lerp=(a,b,t)=>a+(b-a)*(1-Math.exp(-Math.max(0,t)));for(const a of s.ailerons)a.node.rotation.x=lerp(a.node.rotation.x,state.roll*a.side*.42,dt*9);for(const e of s.elevators)e.rotation.x=lerp(e.rotation.x,-state.pitch*.43,dt*9);for(const r of s.rudders)r.rotation.y=lerp(r.rotation.y,-state.yaw*.4,dt*8);for(const f of s.flaps)f.rotation.x=lerp(f.rotation.x,-state.flaps*Math.PI/6,dt*3);for(const g of s.gear){const extension=Math.max(0,Math.min(1,state.gear)),target=1-extension,lowering=(state.gearTarget??state.gear)>0;g.node.setEnabled(lowering||extension>.002);if(g.index===0)g.node.rotation.x=-target*1.45;else g.node.rotation.z=(g.index===1?-1:1)*target*1.45;}for(const w of s.wheels)w.rotation.x-=state.ground?state.speed*dt/.32:dt*.6;advanceRotors(plane,dt,state);}
